
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_c_rge2_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_c_rge2", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-6.984876176528033e-02, -6.881824261860225e-02, -6.733937973286486e-02, -6.521918831538341e-02, -6.218412511885952e-02, -5.785113732443595e-02, -5.170233929644740e-02, -4.312083588776470e-02, -3.177053184858971e-02, -1.937489740326131e-02, -1.426990438757055e-02, -4.109783581453881e-02, -4.781167917905686e-02, -3.479393551099267e-02, -1.884257304952086e-02, -5.026929623658921e-03, -3.090141307548940e-04, -2.908649314557440e-06, -2.997766026254608e-09, -1.186675499604473e-13]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


